# PlanB64 forwarding workspace

Repair the source in `submit/` according to the task instructions. Build with
`make -C /work/submit`. Public input and expected output files are in `examples/`.

The source and fixtures were independently authored for this benchmark. They do
not include PlanB author code or third-party route traces. The research source
is Zhihao Zhang et al., *PlanB: Efficient Software IPv6 Lookup with Linearized
B+-Tree*, NSDI 2026, https://www.usenix.org/conference/nsdi26/presentation/zhang-zhihao.

Only `submit/` is collected. Keep the full buildable source and Makefile there.
=== Makefile
CXX ?= g++
CXXFLAGS ?= -O2 -std=c++17 -Wall -Wextra -Wpedantic

.PHONY: all clean
all: planb64
planb64: planb64.cpp
	$(CXX) $(CPPFLAGS) $(CXXFLAGS) -std=c++17 planb64.cpp $(LDFLAGS) $(LDLIBS) -o $@
clean:
	rm -f planb64
=== planb64.cpp
// PlanB64 experimental interval compiler. Independently written starter code.
#include <arpa/inet.h>
#include <algorithm>
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

struct Row {
    uint64_t start;
    int64_t hop;
    int len;
};
static uint64_t address(const std::string& s) {
    unsigned char bytes[16];
    if (inet_pton(AF_INET6,s.c_str(),bytes)!=1) throw std::runtime_error("invalid address");
    uint64_t key=0;
    for (int i=0;i<8;++i) key=(key<<8)|bytes[i];
    return key;
}
static std::ifstream open(const std::string& p) {
    std::ifstream in(p);
    if (!in) throw std::runtime_error("cannot open file");
    return in;
}
static std::vector<Row> compile(const std::string& path) {
    auto in=open(path);
    std::vector<Row> rows{{0,-1,-1}};
    std::string line;
    while (std::getline(in,line)) {
        if (line.empty()) continue;
        std::istringstream record(line);
        std::string prefix;
        int64_t hop;
        if (!(record>>prefix>>hop)) throw std::runtime_error("bad FIB row");
        auto slash=prefix.find('/');
        if (slash==std::string::npos) throw std::runtime_error("bad prefix");
        int len=std::stoi(prefix.substr(slash+1));
        if (len>64) continue;
        uint64_t key=address(prefix.substr(0,slash));
        if (len==0) key=0;
        else key &= UINT64_MAX<<(64-len);
        rows.push_back({key,hop,len});
    }
    std::sort(rows.begin(),rows.end(),[](const Row& a,const Row& b){return a.start<b.start;});
    std::vector<Row> unique;
    for (const auto& row:rows) {
        if (!unique.empty() && unique.back().start==row.start) unique.back()=row;
        else unique.push_back(row);
    }
    return unique;
}
static void save(const std::string& path,const std::vector<Row>& rows) {
    std::ofstream out(path);
    if (!out) throw std::runtime_error("cannot write image");
    out<<"PLANB64 1\n"<<rows.size()<<'\n';
    for (const auto& r:rows)
        out<<std::hex<<std::setfill('0')<<std::setw(16)<<r.start<<std::dec<<' '<<r.hop<<' '<<r.len<<'\n';
}
static std::vector<Row> load(const std::string& path) {
    auto in=open(path);
    std::string header;
    size_t count;
    std::getline(in,header);
    if (header!="PLANB64 1" || !(in>>count)) throw std::runtime_error("bad image");
    std::vector<Row> rows(count);
    for (auto& row:rows)
        if (!(in>>std::hex>>row.start>>std::dec>>row.hop>>row.len)) throw std::runtime_error("bad image row");
    return rows;
}
static Row lookup(const std::vector<Row>& rows,uint64_t key) {
    auto it=std::lower_bound(rows.begin(),rows.end(),key,
                            [](const Row& r,uint64_t k){return r.start<k;});
    if (it==rows.begin()) return {0,-1,-1};
    return *--it;
}
int main(int argc,char** argv) {
    try {
        if (argc==4 && std::string(argv[1])=="build") {
            save(argv[3],compile(argv[2]));
            return 0;
        }
        if (argc<5 || std::string(argv[1])!="lookup") throw std::runtime_error("usage");
        auto rows=load(argv[2]);
        auto in=open(argv[3]);
        std::vector<uint64_t> queries;
        std::string line;
        while (std::getline(in,line)) if (!line.empty()) queries.push_back(address(line));
        std::string mode=argv[4];
        if (mode=="scalar" && argc==5) {
            for (auto q:queries) {
                auto r=lookup(rows,q);
                std::cout<<r.hop<<' '<<r.len<<'\n';
            }
        } else if (mode=="batch" && argc==6) {
            size_t batch=std::stoul(argv[5]);
            if (batch==0 || batch>256) throw std::runtime_error("bad batch");
            for (size_t i=0;i+batch<=queries.size();i+=batch) {
                for (size_t j=0;j<batch;++j) {
                    auto r=lookup(rows,queries[i+j]);
                    std::cout<<r.hop<<' '<<r.len<<'\n';
                }
            }
        } else throw std::runtime_error("usage");
        return 0;
    } catch (const std::exception& e) {
        std::cerr<<"ERROR: "<<e.what()<<'\n';
        return 2;
    }
}

