mkdir -p /work/submit && cat > /work/submit/planb64.cpp <<'EOF'
// PlanB64: offline IPv6 FIB compiler and longest-prefix lookup tool.
//
// Longest-prefix matching over prefixes of length at most 64 is reduced to
// predecessor search over disjoint intervals of the 64-bit upper-address key
// space.  `build` compiles a FIB into the minimal change-point representation
// of the function  key -> (next hop, prefix length);  `lookup` answers trace
// queries with a binary search over the compiled rows.
//
// Compilation idea.  A prefix of length L covers the aligned dyadic key range
// [start, start + 2^(64-L)).  Dyadic ranges are laminar: two of them either
// nest or are disjoint.  Hence at any candidate change point the covering
// prefixes form a chain ordered by length, so a single stack sweep over the
// sorted candidate boundaries yields the winning route of every elementary
// interval in O(n log n).  Candidate boundaries are exactly 0 plus every
// prefix start plus every prefix end below 2^64, which bounds the row count by
// 2*records + 1.

#include <arpa/inet.h>

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

namespace {

// ------------------------------------------------------------------ limits

constexpr std::size_t kMaxFibRecords = 200000;
constexpr std::size_t kMaxTraceRecords = 1000000;
constexpr std::size_t kMaxLineBytes = 256;
constexpr std::size_t kMaxRows = 400001;
constexpr std::uint64_t kImageByteCap = 64ull * 1024ull * 1024ull;

[[noreturn]] void fail(const std::string& msg) { throw std::runtime_error(msg); }

// ------------------------------------------------------------- text helpers

void append_hex16(std::string& out, std::uint64_t v) {
    static const char digits[] = "0123456789abcdef";
    char buf[16];
    for (int i = 15; i >= 0; --i) {
        buf[i] = digits[v & 0xf];
        v >>= 4;
    }
    out.append(buf, sizeof buf);
}

// Unpadded decimal; the only negative value that can occur is -1.
void append_dec(std::string& out, std::int64_t v) {
    if (v < 0) {
        out.append("-1", 2);
        return;
    }
    char buf[20];
    int i = 20;
    std::uint64_t u = static_cast<std::uint64_t>(v);
    do {
        buf[--i] = static_cast<char>('0' + (u % 10));
        u /= 10;
    } while (u != 0);
    out.append(buf + i, static_cast<std::size_t>(20 - i));
}

bool is_record_ws(char c) { return c == ' ' || c == '\t' || c == '\r'; }

// Splits a line into whitespace-separated fields (space, tab, CR).
void tokenize(const std::string& line, std::vector<std::string_view>& out) {
    out.clear();
    const std::size_t n = line.size();
    std::size_t i = 0;
    while (i < n) {
        while (i < n && is_record_ws(line[i])) ++i;
        if (i == n) break;
        std::size_t s = i;
        while (i < n && !is_record_ws(line[i])) ++i;
        out.emplace_back(line.data() + s, i - s);
    }
}

// --------------------------------------------------------------- file input

// Reads a whole (small) file, refusing anything beyond `cap` bytes.
std::string read_file(const std::string& path, std::uint64_t cap) {
    std::ifstream in(path, std::ios::binary);
    if (!in.is_open()) fail("cannot open input file: " + path);
    in.seekg(0, std::ios::end);
    if (!in.fail()) {
        const std::streamoff sz = in.tellg();
        if (sz >= 0 && static_cast<std::uint64_t>(sz) > cap)
            fail("input file too large: " + path);
        in.clear();
    }
    in.seekg(0, std::ios::beg);
    if (in.fail()) fail("cannot read input file: " + path);
    std::string data;
    char chunk[65536];
    for (;;) {
        in.read(chunk, sizeof chunk);
        const std::streamsize got = in.gcount();
        if (got > 0) {
            if (data.size() + static_cast<std::size_t>(got) > cap)
                fail("input file too large: " + path);
            data.append(chunk, static_cast<std::size_t>(got));
        }
        if (in.eof()) break;
        if (in.bad()) fail("error reading input file: " + path);
        if (got == 0) break;
    }
    return data;
}

// Streams a text file line by line without holding it in memory.  A final line
// without a trailing newline is still a line; overlong lines are rejected.
class LineReader {
  public:
    explicit LineReader(const std::string& path) : in_(path, std::ios::binary) {
        if (!in_.is_open()) fail("cannot open input file: " + path);
    }

    bool next(std::string& line) {
        if (done_) return false;
        for (;;) {
            const std::size_t nl = buf_.find('\n', pos_);
            if (nl != std::string::npos) {
                line.assign(buf_, pos_, nl - pos_);
                pos_ = nl + 1;
                return true;
            }
            if (at_eof_) {
                done_ = true;
                if (pos_ < buf_.size()) {
                    line.assign(buf_, pos_, buf_.size() - pos_);
                    pos_ = buf_.size();
                    return true;
                }
                return false;
            }
            if (pos_ > 0) {
                buf_.erase(0, pos_);
                pos_ = 0;
            }
            char chunk[65536];
            in_.read(chunk, sizeof chunk);
            const std::streamsize got = in_.gcount();
            if (got > 0) buf_.append(chunk, static_cast<std::size_t>(got));
            if (in_.eof()) at_eof_ = true;
            else if (in_.bad()) fail("error reading input file");
            if (buf_.size() > kMaxLineBytes) fail("input line too long");
        }
    }

  private:
    std::ifstream in_;
    std::string buf_;
    std::size_t pos_ = 0;
    bool at_eof_ = false;
    bool done_ = false;
};

// ---------------------------------------------------------------- addresses

// Validates a full IPv6 address with inet_pton(3) and returns its upper
// 64 bits, which is the lookup key for prefixes of length at most 64.
std::uint64_t address_key(const char* begin, std::size_t len) {
    if (len == 0 || len > kMaxLineBytes) fail("invalid IPv6 address");
    char text[kMaxLineBytes + 1];
    std::memcpy(text, begin, len);
    text[len] = '\0';
    in6_addr addr;
    if (inet_pton(AF_INET6, text, &addr) != 1) fail("invalid IPv6 address");
    std::uint64_t key = 0;
    for (int i = 0; i < 8; ++i)
        key = (key << 8) | static_cast<std::uint64_t>(addr.s6_addr[i]);
    return key;
}

// ------------------------------------------------------- decimal field parse

// Accepts ASCII decimal digits with leading zeros; the value must fit `maxv`.
std::uint64_t parse_unsigned_input(std::string_view s, std::uint64_t maxv,
                                   const char* what) {
    if (s.empty()) fail(std::string("invalid ") + what);
    for (char c : s)
        if (c < '0' || c > '9') fail(std::string("invalid ") + what);
    std::size_t i = 0;
    while (i < s.size() && s[i] == '0') ++i;  // leading zeros are allowed
    const std::string_view t = s.substr(i);    // empty means zero
    if (t.size() > 10) fail(std::string("invalid ") + what);
    std::uint64_t v = 0;
    for (char c : t) v = v * 10 + static_cast<std::uint64_t>(c - '0');
    if (v > maxv) fail(std::string("invalid ") + what);
    return v;
}

// ------------------------------------------------------------------ the FIB

struct Prefix {
    std::uint64_t start;  // normalized network, upper 64 bits, host bits clear
    std::uint32_t hop;
    std::uint8_t len;
};

std::vector<Prefix> parse_fib(const std::string& path) {
    LineReader in(path);
    std::string line;
    std::vector<std::string_view> fields;
    std::vector<Prefix> prefixes;
    while (in.next(line)) {
        tokenize(line, fields);
        if (fields.empty()) continue;  // blank line
        if (fields.size() != 2) fail("malformed FIB record");
        const std::string_view spec = fields[0];
        const std::size_t slash = spec.find('/');
        if (slash == std::string_view::npos) fail("malformed FIB prefix");
        const std::uint64_t len =
            parse_unsigned_input(spec.substr(slash + 1), 64, "prefix length");
        const std::uint64_t key = address_key(spec.data(), slash);
        const std::uint64_t hop =
            parse_unsigned_input(fields[1], 4294967295ull, "next hop");
        const std::uint64_t start =
            (len == 0) ? 0 : (key & (~0ull << (64 - len)));
        prefixes.push_back(Prefix{start, static_cast<std::uint32_t>(hop),
                                 static_cast<std::uint8_t>(len)});
        if (prefixes.size() > kMaxFibRecords) fail("too many FIB records");
    }
    return prefixes;
}

// ------------------------------------------------------------- compilation

struct Row {
    std::uint64_t start;
    std::int32_t hop;  // -1 when no route matches
    std::int32_t len;  // -1 when no route matches
};

// Exclusive end key of a prefix; 0 encodes "ends at 2^64" (no end event),
// which is unambiguous because real ends are always at least 1.
std::uint64_t prefix_end(const Prefix& p) {
    if (p.len == 0) return 0;
    return p.start + (1ull << (64 - p.len));  // wraps to 0 exactly at 2^64
}

std::vector<Row> compile_rows(std::vector<Prefix>& fx) {
    std::sort(fx.begin(), fx.end(), [](const Prefix& a, const Prefix& b) {
        if (a.start != b.start) return a.start < b.start;
        return a.len < b.len;
    });
    for (std::size_t i = 1; i < fx.size(); ++i)
        if (fx[i].start == fx[i - 1].start && fx[i].len == fx[i - 1].len)
            fail("duplicate normalized prefix");

    // Candidate change points: 0 plus every prefix start and every prefix end.
    std::vector<std::uint64_t> bounds;
    bounds.reserve(fx.size() * 2 + 1);
    bounds.push_back(0);
    for (const Prefix& p : fx) {
        bounds.push_back(p.start);
        const std::uint64_t end = prefix_end(p);
        if (end != 0) bounds.push_back(end);
    }
    std::sort(bounds.begin(), bounds.end());
    bounds.erase(std::unique(bounds.begin(), bounds.end()), bounds.end());
    if (bounds.size() > kMaxRows) fail("compiled image has too many rows");

    struct Active {
        std::uint64_t end;  // 0 means "no end inside the key space"
        std::uint32_t hop;
        std::uint8_t len;
    };
    std::vector<Active> stack;  // covering prefixes, increasing length upward
    std::vector<Row> rows;
    rows.reserve(bounds.size());
    std::size_t next_prefix = 0;
    for (const std::uint64_t b : bounds) {
        while (!stack.empty() && stack.back().end != 0 && stack.back().end <= b)
            stack.pop_back();
        while (next_prefix < fx.size() && fx[next_prefix].start == b) {
            const Prefix& p = fx[next_prefix];
            stack.push_back(Active{prefix_end(p), p.hop, p.len});
            ++next_prefix;
        }
        std::int32_t hop = -1, len = -1;
        if (!stack.empty()) {
            hop = static_cast<std::int32_t>(stack.back().hop);
            len = static_cast<std::int32_t>(stack.back().len);
        }
        if (rows.empty() || rows.back().hop != hop || rows.back().len != len)
            rows.push_back(Row{b, hop, len});
    }
    return rows;
}

std::string serialize_image(const std::vector<Row>& rows) {
    std::string out;
    out.reserve(24 + rows.size() * 32);
    out.append("PLANB64 1\n");
    out.append(std::to_string(rows.size()));
    out.push_back('\n');
    for (const Row& r : rows) {
        append_hex16(out, r.start);
        out.push_back(' ');
        append_dec(out, r.hop);
        out.push_back(' ');
        append_dec(out, r.len);
        out.push_back('\n');
    }
    return out;
}

// Writes `data` to `path` without disturbing it unless everything succeeds.
void write_image(const std::string& path, const std::string& data) {
    const std::string tmp = path + ".planb64-tmp";
    std::FILE* f = std::fopen(tmp.c_str(), "wb");
    if (f == nullptr) fail("cannot create output file: " + path);
    bool ok = true;
    if (!data.empty() &&
        std::fwrite(data.data(), 1, data.size(), f) != data.size())
        ok = false;
    if (ok && std::fflush(f) != 0) ok = false;
    if (std::fclose(f) != 0) ok = false;
    if (!ok) {
        std::remove(tmp.c_str());
        fail("cannot write output file: " + path);
    }
    if (std::rename(tmp.c_str(), path.c_str()) != 0) {
        std::remove(tmp.c_str());
        fail("cannot install output file: " + path);
    }
}

// ------------------------------------------------------------ image reading

// Canonical image field: "-1" or unpadded decimal within range.
std::int64_t parse_image_field(std::string_view s, std::uint64_t maxv,
                               const char* what) {
    if (s == std::string_view("-1")) return -1;
    const std::string prefix = std::string("malformed image ") + what;
    if (s.empty()) fail(prefix);
    if (s.size() > 10) fail(prefix);
    for (char c : s)
        if (c < '0' || c > '9') fail(prefix);
    if (s.size() > 1 && s[0] == '0') fail(prefix);  // padded spelling
    std::uint64_t v = 0;
    for (char c : s) v = v * 10 + static_cast<std::uint64_t>(c - '0');
    if (v > maxv) fail(prefix);
    return static_cast<std::int64_t>(v);
}

Row parse_image_row(std::string_view s) {
    if (s.size() < 20) fail("malformed image row");
    std::uint64_t start = 0;
    for (std::size_t i = 0; i < 16; ++i) {
        const char c = s[i];
        std::uint64_t d;
        if (c >= '0' && c <= '9') d = static_cast<std::uint64_t>(c - '0');
        else if (c >= 'a' && c <= 'f') d = static_cast<std::uint64_t>(c - 'a') + 10;
        else fail("malformed image row key");
        start = (start << 4) | d;
    }
    if (s[16] != ' ') fail("malformed image row spacing");
    const std::size_t second = s.find(' ', 17);
    if (second == std::string_view::npos || second == 17)
        fail("malformed image row spacing");
    const std::string_view hop_text = s.substr(17, second - 17);
    const std::string_view len_text = s.substr(second + 1);
    if (len_text.empty() || len_text.find(' ') != std::string_view::npos)
        fail("malformed image row spacing");
    const std::int64_t hop = parse_image_field(hop_text, 4294967295ull, "next hop");
    const std::int64_t len = parse_image_field(len_text, 64, "prefix length");
    if ((hop < 0) != (len < 0)) fail("malformed image row pair");
    return Row{start, static_cast<std::int32_t>(hop),
               static_cast<std::int32_t>(len)};
}

std::vector<Row> load_image(const std::string& path) {
    const std::string data = read_file(path, kImageByteCap);
    if (data.empty() || data.back() != '\n')
        fail("malformed image: missing final newline");
    std::size_t pos = 0;
    auto next_line = [&](std::string_view& out) -> bool {
        if (pos >= data.size()) return false;
        const std::size_t nl = data.find('\n', pos);  // always found
        out = std::string_view(data.data() + pos, nl - pos);
        pos = nl + 1;
        return true;
    };

    std::string_view line;
    if (!next_line(line) || line != std::string_view("PLANB64 1"))
        fail("malformed image header");
    if (!next_line(line)) fail("malformed image: missing row count");
    if (line.empty() || line.size() > 6) fail("malformed image row count");
    for (char c : line)
        if (c < '0' || c > '9') fail("malformed image row count");
    if (line.size() > 1 && line[0] == '0') fail("malformed image row count");
    std::uint64_t count = 0;
    for (char c : line) count = count * 10 + static_cast<std::uint64_t>(c - '0');
    if (count < 1 || count > kMaxRows) fail("malformed image row count");

    std::vector<Row> rows;
    rows.reserve(static_cast<std::size_t>(count));
    for (std::uint64_t i = 0; i < count; ++i) {
        if (!next_line(line)) fail("malformed image: fewer rows than declared");
        const Row r = parse_image_row(line);
        if (i == 0) {
            if (r.start != 0) fail("malformed image: first key must be zero");
        } else {
            const Row& prev = rows.back();
            if (r.start <= prev.start) fail("malformed image: keys not strictly increasing");
            if (r.hop == prev.hop && r.len == prev.len)
                fail("malformed image: equal adjacent pairs");
        }
        rows.push_back(r);
    }
    if (next_line(line)) fail("malformed image: extra records");
    return rows;
}

// ---------------------------------------------------------------- the trace

std::vector<std::uint64_t> parse_trace(const std::string& path) {
    LineReader in(path);
    std::string line;
    std::vector<std::string_view> fields;
    std::vector<std::uint64_t> keys;
    while (in.next(line)) {
        tokenize(line, fields);
        if (fields.empty()) continue;  // blank line
        if (fields.size() != 1) fail("malformed trace record");
        keys.push_back(address_key(fields[0].data(), fields[0].size()));
        if (keys.size() > kMaxTraceRecords) fail("too many trace records");
    }
    return keys;
}

// ------------------------------------------------------------------ lookups

// Answers every query with a predecessor search over the interval rows.
// `batch` only controls how many queries are resolved per iteration; the
// semantics are identical to the scalar path.
void emit_answers(const std::vector<Row>& rows,
                  const std::vector<std::uint64_t>& keys, std::size_t batch) {
    std::string out;
    out.reserve(keys.size() * 6 + 64);
    std::size_t i = 0;
    while (i < keys.size()) {
        const std::size_t n = std::min(batch, keys.size() - i);
        for (std::size_t j = 0; j < n; ++j) {
            const std::uint64_t key = keys[i + j];
            std::size_t lo = 0, hi = rows.size();
            while (lo < hi) {  // first row with start > key
                const std::size_t mid = lo + (hi - lo) / 2;
                if (rows[mid].start <= key) lo = mid + 1;
                else hi = mid;
            }
            const Row& r = rows[lo - 1];  // rows[0].start == 0, so lo >= 1
            append_dec(out, r.hop);
            out.push_back(' ');
            append_dec(out, r.len);
            out.push_back('\n');
        }
        i += n;
    }
    if (!out.empty() &&
        std::fwrite(out.data(), 1, out.size(), stdout) != out.size())
        fail("cannot write output");
    if (std::fflush(stdout) != 0) fail("cannot write output");
}

std::size_t parse_batch_size(const char* text) {
    const std::string_view s(text);
    if (s.empty()) fail("invalid batch size");
    for (char c : s)
        if (c < '0' || c > '9') fail("invalid batch size");
    std::size_t i = 0;
    while (i < s.size() && s[i] == '0') ++i;  // leading zeros are allowed
    const std::string_view t = s.substr(i);
    if (t.empty()) fail("invalid batch size");  // value zero
    if (t.size() > 3) fail("invalid batch size");  // greater than 256
    std::uint64_t v = 0;
    for (char c : t) v = v * 10 + static_cast<std::uint64_t>(c - '0');
    if (v < 1 || v > 256) fail("invalid batch size");
    return static_cast<std::size_t>(v);
}

}  // namespace

int main(int argc, char** argv) {
    try {
        if (argc == 4 && std::strcmp(argv[1], "build") == 0) {
            std::vector<Prefix> fx = parse_fib(argv[2]);
            const std::vector<Row> rows = compile_rows(fx);
            write_image(argv[3], serialize_image(rows));
            return 0;
        }
        if (std::strcmp(argv[1], "lookup") == 0 && argc >= 5) {
            if (argc == 5 && std::strcmp(argv[4], "scalar") == 0) {
                const std::vector<Row> rows = load_image(argv[2]);
                const std::vector<std::uint64_t> keys = parse_trace(argv[3]);
                emit_answers(rows, keys, 1);
                return 0;
            }
            if (argc == 6 && std::strcmp(argv[4], "batch") == 0) {
                const std::size_t batch = parse_batch_size(argv[5]);
                const std::vector<Row> rows = load_image(argv[2]);
                const std::vector<std::uint64_t> keys = parse_trace(argv[3]);
                emit_answers(rows, keys, batch);
                return 0;
            }
        }
        fail("usage: planb64 build FIB IMAGE | planb64 lookup IMAGE TRACE scalar"
             " | planb64 lookup IMAGE TRACE batch BATCH_SIZE");
    } catch (const std::exception& e) {
        std::fprintf(stderr, "ERROR: %s\n", e.what());
        return 2;
    } catch (...) {
        std::fprintf(stderr, "ERROR: unexpected failure\n");
        return 2;
    }
}
