 31	
 32	// ------------------------------------------------------------------ limits
 33	
 34	constexpr std::size_t kMaxFibRecords = 200000;
 35	constexpr std::size_t kMaxTraceRecords = 1000000;
 36	constexpr std::size_t kMaxLineBytes = 256;
 37	constexpr std::size_t kMaxRows = 400001;
 38	constexpr std::uint64_t kImageByteCap = 64ull * 1024ull * 1024ull;
 39	
 40	[[noreturn]] void fail(const std::string& msg) { throw std::runtime_error(msg); }
 41	
 42	// ------------------------------------------------------------- text helpers
 43	
 44	void append_hex16(std::string& out, std::uint64_t v) {
 45	    static const char digits[] = "0123456789abcdef";
 46	    char buf[16];
 47	    for (int i = 15; i >= 0; --i) {
 48	        buf[i] = digits[v & 0xf];
 49	        v >>= 4;
 50	    }
 51	    out.append(buf, sizeof buf);
 52	}
 53	
 54	// Unpadded decimal; the only negative value that can occur is -1.
 55	void append_dec(std::string& out, std::int64_t v) {
 56	    if (v < 0) {
 57	        out.append("-1", 2);
 58	        return;
 59	    }
 60	    char buf[20];
 61	    int i = 20;
 62	    std::uint64_t u = static_cast<std::uint64_t>(v);
 63	    do {
 64	        buf[--i] = static_cast<char>('0' + (u % 10));
 65	        u /= 10;
 66	    } while (u != 0);
 67	    out.append(buf + i, static_cast<std::size_t>(20 - i));
 68	}
 69	
 70	bool is_record_ws(char c) { return c == ' ' || c == '\t' || c == '\r'; }
 71	
 72	// Splits a line into whitespace-separated fields (space, tab, CR).
 73	void tokenize(const std::string& line, std::vector<std::string_view>& out) {
 74	    out.clear();
 75	    const std::size_t n = line.size();
 76	    std::size_t i = 0;
 77	    while (i < n) {
 78	        while (i < n && is_record_ws(line[i])) ++i;
 79	        if (i == n) break;
 80	        std::size_t s = i;
 81	        while (i < n && !is_record_ws(line[i])) ++i;
 82	        out.emplace_back(line.data() + s, i - s);
 83	    }
 84	}
