237	// ------------------------------------------------------------- compilation
238	
239	struct Row {
240	    std::uint64_t start;
241	    std::uint32_t hop;  // meaningful only when len >= 0
242	    std::int32_t len;   // -1 when no route matches
243	};
244	
245	// Exclusive end key of a prefix; 0 encodes "ends at 2^64" (no end event),
246	// which is unambiguous because real ends are always at least 1.
247	std::uint64_t prefix_end(const Prefix& p) {
248	    if (p.len == 0) return 0;
249	    return p.start + (1ull << (64 - p.len));  // wraps to 0 exactly at 2^64
250	}
251	
252	std::vector<Row> compile_rows(std::vector<Prefix>& fx) {
253	    std::sort(fx.begin(), fx.end(), [](const Prefix& a, const Prefix& b) {
254	        if (a.start != b.start) return a.start < b.start;
255	        return a.len < b.len;
256	    });
257	    for (std::size_t i = 1; i < fx.size(); ++i)
258	        if (fx[i].start == fx[i - 1].start && fx[i].len == fx[i - 1].len)
259	            fail("duplicate normalized prefix");
260	
261	    // Candidate change points: 0 plus every prefix start and every prefix end.
262	    std::vector<std::uint64_t> bounds;
263	    bounds.reserve(fx.size() * 2 + 1);
264	    bounds.push_back(0);
265	    for (const Prefix& p : fx) {
266	        bounds.push_back(p.start);
267	        const std::uint64_t end = prefix_end(p);
268	        if (end != 0) bounds.push_back(end);
269	    }
270	    std::sort(bounds.begin(), bounds.end());
271	    bounds.erase(std::unique(bounds.begin(), bounds.end()), bounds.end());
272	    if (bounds.size() > kMaxRows) fail("compiled image has too many rows");
273	
274	    struct Active {
275	        std::uint64_t end;  // 0 means "no end inside the key space"
276	        std::uint32_t hop;
277	        std::uint8_t len;
278	    };
279	    std::vector<Active> stack;  // covering prefixes, increasing length upward
280	    std::vector<Row> rows;
281	    rows.reserve(bounds.size());
282	    std::size_t next_prefix = 0;
283	    for (const std::uint64_t b : bounds) {
284	        while (!stack.empty() && stack.back().end != 0 && stack.back().end <= b)
285	            stack.pop_back();
286	        while (next_prefix < fx.size() && fx[next_prefix].start == b) {
287	            const Prefix& p = fx[next_prefix];
288	            stack.push_back(Active{prefix_end(p), p.hop, p.len});
289	            ++next_prefix;
290	        }
291	        std::uint32_t hop = 0;
292	        std::int32_t len = -1;
293	        if (!stack.empty()) {
294	            hop = stack.back().hop;
295	            len = static_cast<std::int32_t>(stack.back().len);
296	        }
297	        if (rows.empty() || rows.back().hop != hop || rows.back().len != len)
298	            rows.push_back(Row{b, hop, len});
299	    }
300	    return rows;
301	}
302	
303	std::string serialize_image(const std::vector<Row>& rows) {
304	    std::string out;
305	    out.reserve(24 + rows.size() * 32);
306	    out.append("PLANB64 1\n");
307	    out.append(std::to_string(rows.size()));
308	    out.push_back('\n');
309	    for (const Row& r : rows) {
310	        append_hex16(out, r.start);
311	        out.push_back(' ');
312	        if (r.len < 0) out.append("-1 -1", 5);
313	        else {
314	            append_dec(out, static_cast<std::int64_t>(r.hop));
315	            out.push_back(' ');
316	            append_dec(out, r.len);
317	        }
318	        out.push_back('\n');
319	    }
320	    return out;
321	}
