323	// Writes `data` to `path` without disturbing it unless everything succeeds.
324	void write_image(const std::string& path, const std::string& data) {
325	    const std::string tmp = path + ".planb64-tmp";
326	    std::FILE* f = std::fopen(tmp.c_str(), "wb");
327	    if (f == nullptr) fail("cannot create output file: " + path);
328	    bool ok = true;
329	    if (!data.empty() &&
330	        std::fwrite(data.data(), 1, data.size(), f) != data.size())
331	        ok = false;
332	    if (ok && std::fflush(f) != 0) ok = false;
333	    if (std::fclose(f) != 0) ok = false;
334	    if (!ok) {
335	        std::remove(tmp.c_str());
336	        fail("cannot write output file: " + path);
337	    }
338	    if (std::rename(tmp.c_str(), path.c_str()) != 0) {
339	        std::remove(tmp.c_str());
340	        fail("cannot install output file: " + path);
341	    }
342	}
